SELECT DISTINCT ?concept ?label WHERE {
  VALUES ?target { <urn:visual:target> }
  VALUES ?conceptType { owl:Class skos:Concept }
  ?concept rdf:type ?conceptType .
  ?concept <urn:visual:property> ?target .
  OPTIONAL { ?concept rdfs:label ?label . }
}
LIMIT 100

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?concept ?label WHERE {
  VALUES ?target { <urn:visual:target> }
  VALUES ?conceptType { owl:Class skos:Concept }
  ?concept rdf:type ?conceptType .
  <urn:visual:property> rdfs:domain ?concept ; rdfs:range ?target .
  OPTIONAL { ?concept rdfs:label ?label . }
}
LIMIT 100

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?concept ?label WHERE {
  VALUES ?target { <urn:visual:target> }
  VALUES ?conceptType { owl:Class skos:Concept }
  ?concept rdf:type ?conceptType .
  ?concept rdfs:subClassOf [ a owl:Restriction ; owl:onProperty <urn:visual:property> ; owl:someValuesFrom ?target ] .
  OPTIONAL { ?concept rdfs:label ?label . }
}
LIMIT 100

